def check_k_elements(collection: Iterable[Tuple[int, ...]], k: int) -> bool:
    found = set()
    for tup in collection:
        for item in tup:
            if 1 <= item <= k:
                found.add(item)
            if len(found) == k:
                return True
    return len(found) == k
