    if all(ch == '9' for ch in s):
        return num + 2  # e.g. 9 -> 11, 99 -> 101

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    # Increment the palindrome by adjusting the middle part
    def increment_mid(left: str, odd_length: bool) -> str:
        if odd_length:
            mid = left[-1]
            left_part = left[:-1]
            mid_int = int(mid) + 1
            if mid_int == 10:
