        else:
            left_int = int(left) + 1
            left_str = str(left_int)
            return make_palindrome(left_str, odd_length)

    # Main logic
    odd_length = (length % 2 != 0)
    mid = length // 2

    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd_length)
    palindrome_int = int(palindrome)

    if palindrome_int > num:
        return palindrome_int
    else:
        # Need to increment the middle part and remake palindrome
        while True:
            if odd_length:
                # Increment left part as integer
                left_int = int(left) + 1
                left = str(left_int)
                palindrome = make_palindrome(left, odd_length)
            else:
