def min_Jumps(d: int, length: int) -> int:
    if d == 0:
        return 0
    if d == length:
        return 1
    if d < length:
        # One jump is too long, but can't land exactly on (d,0) with one jump.
        # Two jumps can cover any distance less than length.
        return 2
    # For d > length, calculate minimum jumps needed
    return math.ceil(d / length)
