import re

def anti_shuffle(s):
    def sort_word(word):
        return ''.join(sorted(word))

    tokens = re.findall(r'\S+|\s+', s)
    result = []
    for token in tokens:
        if token.isspace():
            result.append(token)
        else:
            # Separate trailing non-alpha chars from the word start
            m = re.match(r'^([A-Za-z]+)([^A-Za-z]*)$', token)
            if m:
                word, tail = m.groups()
                sorted_word = sort_word(word)
                sorted_tail = sort_word(tail) if tail else ''
                result.append(sorted_word + sorted_tail)
            else:
                # No alpha chars at start, sort whole token
                result.append(sort_word(token))
    return ''.join(result)
```

