import math

def prime_length(string):
    n = len(string)
    if n < 2:
        return 0
    if n == 2:
        return 1
    # check divisibility by 2
    if n % 2 == 0:
        return 0
    # generate a tuple of possible divisors: odd numbers from 3 to sqrt(n)
    divisors = tuple(range(3, int(math.isqrt(n)) + 1, 2))
    # use all() to check if n is not divisible by any divisor
    return int(all(n % d != 0 for d in divisors))
