def triples_sum_to_zero(nums: list) -> bool:
    n = len(nums)
    if n < 3:
        return False
    nums.sort()
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False
